import * as React from "react"
import * as styles from "../styles/tech_demo.module.scss"

// Layout constants for the diagram, in SVG user units
const TOP = 56
const ROW_GAP = 72
const BOX_H = 48
const GAME_X = 20
const GAME_W = 232
const ENGINE_X = 300
const ENGINE_W = 200
const PROXY_X = 580
const PROXY_W = 180
const RIGHT_X = 840
const RIGHT_W = 272

const GAMES = [
    { name: "Where Winds Meet", engine: 0, demo: true },
    { name: "Avatar: Frontiers of Pandora", engine: 1, demo: true },
    { name: "Assassin's Creed Shadows", engine: 2, demo: true },
    { name: "Crimson Desert", engine: 3, demo: true },
    { name: "Grand Theft Auto V", engine: 4, demo: true },
    { name: "Hogwarts Legacy", engine: 5 },
    { name: "…", engine: 5 },
]

const ENGINES = ["Messiah Engine", "Snowdrop Engine", "Anvil Engine", "BlackSpace Engine", "RAGE Engine", "Unreal Engine"]

const OUTPUTS = [
    { title: "Camera", detail: "Per-frame pose" },
    { title: "Metric Depth", detail: "Per-pixel depth in metric units" },
    { title: "Object Geometric / Material Info", detail: "Scene geometry and materials" },
]

const rowCenter = (i) => TOP + i * ROW_GAP + BOX_H / 2
// The last engine (Unreal) collects every remaining game, so it sits between their rows
const engineCenter = (i) => (i < 5 ? rowCenter(i) : (rowCenter(5) + rowCenter(6)) / 2)

const PROXY_TOP = TOP
const PROXY_BOTTOM = TOP + 6 * ROW_GAP + BOX_H
const D3D_CY = TOP + 36
const OUTPUT_TOP = 192
const OUTPUT_H = 72
const OUTPUT_GAP = 40
const outputCenter = (i) => OUTPUT_TOP + i * (OUTPUT_H + OUTPUT_GAP) + OUTPUT_H / 2

const curve = (x1, y1, x2, y2) => {
    const mx = (x1 + x2) / 2
    return `M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}`
}

const ArchitectureDiagram = () => (
    <svg
        className={styles.diagram}
        viewBox="0 0 1120 560"
        role="img"
        aria-labelledby="arch-title arch-desc"
    >
        <title id="arch-title">Render data extraction architecture</title>
        <desc id="arch-desc">
            Games built on Messiah, Snowdrop, Anvil, BlackSpace, RAGE and Unreal engines all issue calls through a
            Graphics API Proxy. The proxy forwards them to the D3D12 Graphics API and retrieves camera, metric
            depth and object geometric and material information.
        </desc>
        <defs>
            <marker id="arrow-muted" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
                <path d="M0,0 L10,5 L0,10 z" className={styles.arrowMuted} />
            </marker>
            <marker id="arrow-gold" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
                <path d="M0,0 L10,5 L0,10 z" className={styles.arrowGold} />
            </marker>
            <marker id="arrow-teal" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
                <path d="M0,0 L10,5 L0,10 z" className={styles.arrowTeal} />
            </marker>
            <linearGradient id="proxy-fill" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#2a2418" />
                <stop offset="1" stopColor="#1a1712" />
            </linearGradient>
        </defs>

        {/* Column headings */}
        <text x={GAME_X} y={28} className={styles.diagramHeading}>GAME</text>
        <text x={ENGINE_X} y={28} className={styles.diagramHeading}>ENGINE</text>
        <text x={PROXY_X} y={28} className={styles.diagramHeading}>INTERCEPTION</text>
        <text x={RIGHT_X} y={28} className={styles.diagramHeading}>GRAPHICS API &amp; OUTPUT</text>

        {/* Game → engine links */}
        {GAMES.map((game, i) => (
            <path
                key={`link-${game.name}`}
                d={curve(GAME_X + GAME_W, rowCenter(i), ENGINE_X, engineCenter(game.engine))}
                className={styles.linkMuted}
            />
        ))}

        {/* Engine → proxy links */}
        {ENGINES.map((engine, i) => (
            <path
                key={`proxy-link-${engine}`}
                d={`M${ENGINE_X + ENGINE_W},${engineCenter(i)} L${PROXY_X - 2},${engineCenter(i)}`}
                className={styles.linkMuted}
                markerEnd="url(#arrow-muted)"
            />
        ))}

        {/* Games */}
        {GAMES.map((game, i) => (
            <g key={game.name}>
                <rect
                    x={GAME_X}
                    y={TOP + i * ROW_GAP}
                    width={GAME_W}
                    height={BOX_H}
                    rx={7}
                    className={game.demo ? styles.nodeGame : styles.nodeGameFaint}
                />
                {game.demo && <circle cx={GAME_X + 18} cy={rowCenter(i)} r={3.5} className={styles.demoDot} />}
                <text
                    x={game.demo ? GAME_X + 32 : GAME_X + GAME_W / 2}
                    y={rowCenter(i) + 5}
                    textAnchor={game.demo ? "start" : "middle"}
                    className={game.demo ? styles.nodeLabel : styles.nodeLabelFaint}
                >
                    {game.name}
                </text>
            </g>
        ))}

        {/* Engines */}
        {ENGINES.map((engine, i) => (
            <g key={engine}>
                <rect
                    x={ENGINE_X}
                    y={engineCenter(i) - BOX_H / 2}
                    width={ENGINE_W}
                    height={BOX_H}
                    rx={7}
                    className={styles.nodeEngine}
                />
                <text x={ENGINE_X + ENGINE_W / 2} y={engineCenter(i) + 5} textAnchor="middle" className={styles.nodeLabel}>
                    {engine}
                </text>
            </g>
        ))}

        {/* Graphics API Proxy */}
        <rect
            x={PROXY_X}
            y={PROXY_TOP}
            width={PROXY_W}
            height={PROXY_BOTTOM - PROXY_TOP}
            rx={10}
            fill="url(#proxy-fill)"
            className={styles.nodeProxy}
        />
        <text x={PROXY_X + PROXY_W / 2} y={(PROXY_TOP + PROXY_BOTTOM) / 2 - 14} textAnchor="middle" className={styles.proxyTitle}>
            Graphics API
        </text>
        <text x={PROXY_X + PROXY_W / 2} y={(PROXY_TOP + PROXY_BOTTOM) / 2 + 14} textAnchor="middle" className={styles.proxyTitle}>
            Proxy
        </text>
        <text x={PROXY_X + PROXY_W / 2} y={(PROXY_TOP + PROXY_BOTTOM) / 2 + 44} textAnchor="middle" className={styles.nodeDetail}>
            Engine-agnostic
        </text>
        <text x={PROXY_X + PROXY_W / 2} y={(PROXY_TOP + PROXY_BOTTOM) / 2 + 62} textAnchor="middle" className={styles.nodeDetail}>
            interception layer
        </text>

        {/* Proxy ⇄ D3D12 */}
        <path d={`M${PROXY_X + PROXY_W + 2},${D3D_CY - 9} L${RIGHT_X - 2},${D3D_CY - 9}`} className={styles.linkGold} markerEnd="url(#arrow-gold)" />
        <path d={`M${RIGHT_X - 2},${D3D_CY + 9} L${PROXY_X + PROXY_W + 2},${D3D_CY + 9}`} className={styles.linkGold} markerEnd="url(#arrow-gold)" />
        <text x={(PROXY_X + PROXY_W + RIGHT_X) / 2} y={D3D_CY - 18} textAnchor="middle" className={styles.linkLabel}>calls</text>
        <text x={(PROXY_X + PROXY_W + RIGHT_X) / 2} y={D3D_CY + 30} textAnchor="middle" className={styles.linkLabel}>data</text>

        <rect x={RIGHT_X} y={TOP} width={RIGHT_W} height={72} rx={8} className={styles.nodeApi} />
        <text x={RIGHT_X + 20} y={TOP + 32} className={styles.nodeLabelStrong}>D3D12 Graphics API</text>
        <text x={RIGHT_X + 20} y={TOP + 54} className={styles.nodeDetail}>Native rendering path</text>

        {/* Extracted data */}
        <text x={RIGHT_X} y={OUTPUT_TOP - 14} className={styles.diagramHeading}>EXTRACTED RENDER DATA</text>
        {OUTPUTS.map((output, i) => (
            <g key={output.title}>
                <path
                    d={curve(PROXY_X + PROXY_W + 2, outputCenter(i), RIGHT_X - 2, outputCenter(i))}
                    className={styles.linkTeal}
                    markerEnd="url(#arrow-teal)"
                />
                <rect
                    x={RIGHT_X}
                    y={outputCenter(i) - OUTPUT_H / 2}
                    width={RIGHT_W}
                    height={OUTPUT_H}
                    rx={8}
                    className={styles.nodeOutput}
                />
                <rect x={RIGHT_X} y={outputCenter(i) - OUTPUT_H / 2} width={4} height={OUTPUT_H} rx={2} className={styles.outputAccent} />
                <text x={RIGHT_X + 20} y={outputCenter(i) - 4} className={styles.nodeLabelStrong}>{output.title}</text>
                <text x={RIGHT_X + 20} y={outputCenter(i) + 18} className={styles.nodeDetail}>{output.detail}</text>
            </g>
        ))}
    </svg>
)

export default ArchitectureDiagram
