import * as React from "react"
import * as styles from "../styles/tech_demo.module.scss"

// Load the YouTube IFrame API once and share it between every player on the page
let youTubeApiPromise = null
function loadYouTubeApi() {
    if (window.YT && window.YT.Player) {
        return Promise.resolve(window.YT)
    }
    if (!youTubeApiPromise) {
        youTubeApiPromise = new Promise((resolve) => {
            const previousCallback = window.onYouTubeIframeAPIReady
            window.onYouTubeIframeAPIReady = () => {
                if (previousCallback) previousCallback()
                resolve(window.YT)
            }
            const script = document.createElement("script")
            script.src = "https://www.youtube.com/iframe_api"
            document.head.appendChild(script)
        })
    }
    return youTubeApiPromise
}

const PLAYING = 1
const PAUSED = 2
// Seconds of drift tolerated before the trajectory video is snapped back to the game video
const MAX_DRIFT = 0.6

function formatTime(seconds) {
    const total = Math.max(0, Math.floor(seconds || 0))
    return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`
}

const SyncedVideoPair = ({ demo }) => {
    const gameMountRef = React.useRef(null)
    const trajectoryMountRef = React.useRef(null)
    const gamePlayerRef = React.useRef(null)
    const trajectoryPlayerRef = React.useRef(null)
    const linkedRef = React.useRef(true)

    const [ready, setReady] = React.useState(false)
    const [playing, setPlaying] = React.useState(false)
    const [linked, setLinked] = React.useState(true)
    const [currentTime, setCurrentTime] = React.useState(0)
    const [duration, setDuration] = React.useState(0)

    React.useEffect(() => {
        linkedRef.current = linked
    }, [linked])

    // Recreate both players whenever the selected demo changes
    React.useEffect(() => {
        let cancelled = false
        let readyCount = 0
        setReady(false)
        setPlaying(false)
        setCurrentTime(0)
        setDuration(0)

        // Mirror play/pause from one player onto the other while playback is linked
        const mirrorState = (isGame, getOther) => (event) => {
            if (isGame) {
                setPlaying(event.data === PLAYING)
            }
            const other = getOther()
            if (!linkedRef.current || !other) return
            if (event.data === PLAYING) {
                const drift = Math.abs(event.target.getCurrentTime() - other.getCurrentTime())
                if (drift > MAX_DRIFT) other.seekTo(event.target.getCurrentTime(), true)
                if (other.getPlayerState() !== PLAYING) other.playVideo()
            } else if (event.data === PAUSED && other.getPlayerState() === PLAYING) {
                other.pauseVideo()
            }
        }

        loadYouTubeApi().then((YT) => {
            if (cancelled) return
            const playerVars = { rel: 0, playsinline: 1, modestbranding: 1 }
            const onReady = () => {
                readyCount += 1
                if (readyCount === 2 && !cancelled) {
                    trajectoryPlayerRef.current.mute()
                    setDuration(gamePlayerRef.current.getDuration())
                    setReady(true)
                }
            }
            gamePlayerRef.current = new YT.Player(gameMountRef.current, {
                videoId: demo.gameVideo,
                playerVars,
                events: { onReady, onStateChange: mirrorState(true, () => trajectoryPlayerRef.current) },
            })
            trajectoryPlayerRef.current = new YT.Player(trajectoryMountRef.current, {
                videoId: demo.trajectoryVideo,
                playerVars,
                events: { onReady, onStateChange: mirrorState(false, () => gamePlayerRef.current) },
            })
        })

        return () => {
            cancelled = true
            if (gamePlayerRef.current) gamePlayerRef.current.destroy()
            if (trajectoryPlayerRef.current) trajectoryPlayerRef.current.destroy()
            gamePlayerRef.current = null
            trajectoryPlayerRef.current = null
        }
    }, [demo.gameVideo, demo.trajectoryVideo])

    // Poll the game video's clock to drive the shared timeline
    React.useEffect(() => {
        if (!ready) return undefined
        const timer = window.setInterval(() => {
            const game = gamePlayerRef.current
            if (!game || !game.getCurrentTime) return
            setCurrentTime(game.getCurrentTime())
            const gameDuration = game.getDuration()
            if (gameDuration) setDuration(gameDuration)
        }, 250)
        return () => window.clearInterval(timer)
    }, [ready])

    const playBoth = () => {
        const game = gamePlayerRef.current
        const trajectory = trajectoryPlayerRef.current
        trajectory.seekTo(game.getCurrentTime(), true)
        game.playVideo()
        trajectory.playVideo()
    }

    const pauseBoth = () => {
        gamePlayerRef.current.pauseVideo()
        trajectoryPlayerRef.current.pauseVideo()
    }

    const seekBoth = (seconds) => {
        gamePlayerRef.current.seekTo(seconds, true)
        trajectoryPlayerRef.current.seekTo(seconds, true)
        setCurrentTime(seconds)
    }

    return (
        <div className={styles.comparisonShell}>
            <div className={styles.comparisonGrid}>
                <figure className={styles.videoCard}>
                    <figcaption className={styles.videoHeader}>
                        <span>Game capture</span>
                        <a href={`https://youtu.be/${demo.gameVideo}`} target="_blank" rel="noreferrer" aria-label="Open game video on YouTube">↗</a>
                    </figcaption>
                    <div className={styles.videoWrap}>
                        <div ref={gameMountRef} />
                    </div>
                </figure>
                <figure className={styles.videoCard}>
                    <figcaption className={styles.videoHeader}>
                        <span>Extracted camera trajectory · Blender</span>
                        <a href={`https://youtu.be/${demo.trajectoryVideo}`} target="_blank" rel="noreferrer" aria-label="Open camera trajectory video on YouTube">↗</a>
                    </figcaption>
                    <div className={styles.videoWrap}>
                        <div ref={trajectoryMountRef} />
                    </div>
                </figure>
            </div>

            <div className={styles.playbackToolbar}>
                <button
                    type="button"
                    className={`${styles.button} ${styles.buttonPrimary}`}
                    onClick={playing ? pauseBoth : playBoth}
                    disabled={!ready}
                >
                    {playing ? "❚❚ Pause both" : "▶ Play both"}
                </button>
                <button
                    type="button"
                    className={styles.iconButton}
                    onClick={() => seekBoth(0)}
                    disabled={!ready}
                    aria-label="Restart both videos"
                >
                    ↺
                </button>
                <input
                    type="range"
                    min={0}
                    max={duration || 1}
                    step={0.1}
                    value={Math.min(currentTime, duration || 1)}
                    onChange={(e) => seekBoth(Number(e.target.value))}
                    disabled={!ready}
                    aria-label="Shared timeline"
                />
                <output>{formatTime(currentTime)} / {formatTime(duration)}</output>
            </div>
            <div className={styles.playbackStatus}>
                <label className={styles.linkToggle}>
                    <input type="checkbox" checked={linked} onChange={(e) => setLinked(e.target.checked)} />
                    Link playback
                </label>
                <span>
                    {ready
                        ? "Both videos share one timeline. The trajectory view is muted."
                        : "Loading players…"}
                </span>
            </div>
        </div>
    )
}

export default SyncedVideoPair
